#!/usr/bin/env bash
# Regenerates pylib/requirements.txt, the hash-pinned lock that
# `embedding-lib setup` installs with `pip --require-hashes`, from
# pylib/requirements.in.
#
#   tools/lock.sh <path-to-uv>
#
# requirements.txt is generated by this script, never edited by hand. The
# lock holds hashes for every wheel of each pinned version, so the same file
# installs on x86_64 and aarch64. torch comes from PyTorch's CPU index; the
# CUDA build on PyPI is several GB larger and of no use here.
#
# Changing the lock changes the identity every index records, so the pipeline
# re-embeds after the next release (PLAN §5).
#
# A development tool: not in PAYLOAD, never installed.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
UV="${1:?path to uv}"
. "$HERE/pylib/runtime.env"
PYMINOR="${PY_VERSION%.*}"

cd "$HERE/pylib"
"$UV" pip compile -q --generate-hashes --python-version "$PYMINOR" \
  --index-url https://pypi.org/simple \
  --extra-index-url https://download.pytorch.org/whl/cpu \
  --index-strategy unsafe-best-match \
  --custom-compile-command "tools/lock.sh <uv>" \
  -o requirements.txt requirements.in
grep -E '^[a-zA-Z]' requirements.txt | sed 's/ \\$//'
